"""Pure-Python offline fallback summarizer for Plan Insights."""

from __future__ import annotations

from typing import Any, Dict, List

OFFLINE_DISCLAIMER = (
    "*Note: Generated by the built-in offline Python summarizer (limited capacity — rule-based lookups of your saved plan). "
    "For more comprehensive conversational analysis, consider running a local Ollama model (`llama3.2:latest`) or configuring a cloud LLM key in `.env`.*"
)


def _fmt_money(val: Any) -> str:
    try:
        return f"${float(val or 0):,.0f}"
    except (TypeError, ValueError):
        return "$0"


def summarize_plan_offline(message: str, plan: Dict[str, Any], _module_runs: List[Dict[str, Any]]) -> Dict[str, str]:
    """Pure-Python deterministic fallback summarizer when no local or cloud LLM is configured."""
    q = (message or "").lower()
    payload = plan.get("payload") or {}
    title = plan.get("title") or payload.get("client_name") or "Personal Financial Plan"
    score = float(plan.get("health_score", payload.get("health_score", 0)) or 0)
    grade = plan.get("grade", payload.get("grade", "--")) or "--"
    cats = payload.get("categories") or {}
    cf = payload.get("cash_flow") or {}
    debt = payload.get("debt") or {}
    inv = payload.get("investments") or {}
    ret = payload.get("retirement") or {}
    prot = payload.get("protection") or {}
    mc = ret.get("monte_carlo") or {}
    actions = payload.get("action_items") or []

    pillars = [
        ("Cash Flow", float(cats.get("cash_flow") or 0)),
        ("Debt", float(cats.get("debt") or 0)),
        ("Investments", float(cats.get("investments") or 0)),
        ("Retirement", float(cats.get("retirement") or 0)),
        ("Protection", float(cats.get("protection") or 0)),
    ]
    assessed = [(n, s) for n, s in pillars if s > 0]
    sections: List[str] = []

    if any(k in q for k in ("priorit", "action", "next", "focus", "improve")):
        sections.append(f"### Top Priorities for {title}")
        if actions:
            for i, a in enumerate(actions[:3], 1):
                sections.append(f"{i}. **{a.get('action', '')}** ({a.get('category', 'Plan')} • {a.get('priority', 'Med')} priority)")
        else:
            sections.append("- No action items saved yet. Run and save the `★` modules to generate prioritized actions.")
    elif any(k in q for k in ("retire", "fire", "monte", "mc", "odds", "survival")):
        sections.append(f"### Retirement & Monte Carlo Outlook ({title})")
        sections.append(f"- **Current Balance:** {_fmt_money(ret.get('current_balance'))} (Target: {_fmt_money(ret.get('target_balance'))})")
        sections.append(f"- **Monthly Contribution:** {_fmt_money(ret.get('monthly_contribution'))}/mo (+{_fmt_money(ret.get('employer_match_monthly'))}/mo match)")
        if mc:
            sections.append(f"- **Monte Carlo Survival:** {float(mc.get('success_rate_pct') or 0):.1f}% (Median @ retirement: {_fmt_money(mc.get('retire_p50'))})")
        else:
            sections.append("- Monte Carlo results are not saved yet. Open **Retirement & FI Planner** and click **Save to My Plan**.")
    elif any(k in q for k in ("debt", "loan", "apr", "card")):
        accounts = debt.get("accounts") or []
        total_debt = sum(float(a.get("balance") or 0) for a in accounts)
        sections.append(f"### Debt Summary ({title})")
        sections.append(f"- **Total Debt:** {_fmt_money(total_debt)} across {len(accounts)} account(s) (Debt Score: {cats.get('debt', 0)}/100)")
        for a in accounts[:5]:
            sections.append(f"- **{a.get('name', 'Account')}:** {_fmt_money(a.get('balance'))} at {float(a.get('apr') or 0):.1f}% APR")
    elif any(k in q for k in ("cash", "budget", "income", "save", "spend")):
        b = cf.get("budget_50_30_20") or {}
        sections.append(f"### Cash Flow & Budget ({title})")
        sections.append(f"- **Monthly Take-Home:** {_fmt_money(cf.get('monthly_income'))} (Cash Flow Score: {cats.get('cash_flow', 0)}/100)")
        if b:
            sections.append(f"- **50/30/20 Split:** Needs {_fmt_money(b.get('needs'))} • Wants {_fmt_money(b.get('wants'))} • Savings {_fmt_money(b.get('savings'))}")
    elif any(k in q for k in ("invest", "portfolio", "stock", "bond", "alloc")):
        alloc = inv.get("allocation") or []
        sections.append(f"### Portfolio Summary ({title})")
        sections.append(f"- **Total Invested Value:** {_fmt_money(inv.get('total_value'))} (Investments Score: {cats.get('investments', 0)}/100)")
        for a in alloc:
            sections.append(f"- **{a.get('name', 'Asset')}:** {float(a.get('pct') or 0):.1f}% (Target: {float(a.get('target_pct') or 0):.1f}%)")
    elif any(k in q for k in ("protect", "insur", "estate", "will", "life")):
        items = prot.get("items") or []
        sections.append(f"### Protection & Estate ({title})")
        sections.append(f"- **Protection Score:** {cats.get('protection', 0)}/100")
        for it in items:
            sections.append(f"- **{it.get('name', 'Item')}:** {it.get('status', 'Unknown')}")
    else:
        sections.append(f"### Financial Health Summary: {score:.1f}/100 (Grade {grade})")
        if assessed:
            strongest = max(assessed, key=lambda x: x[1])
            weakest = min(assessed, key=lambda x: x[1])
            sections.append(f"- **Strongest:** {strongest[0]} ({round(strongest[1])}/100) • **Lowest:** {weakest[0]} ({round(weakest[1])}/100)")
            sections.append("| Category | Score |")
            sections.append("|---|---|")
            for name, sc in pillars:
                sections.append(f"| {name} | {f'{round(sc)}/100' if sc > 0 else 'Not assessed'} |")
        else:
            sections.append("- No `★` modules have been saved to this plan yet. Open any `★` module and click **Save to My Plan (`✓✓`)**.")
        if actions:
            sections.append(f"- **Top Action:** {actions[0].get('action', '')}")

    sections.append(f"\n---\n{OFFLINE_DISCLAIMER}")
    return {"reply": "\n".join(sections), "model": "offline-python"}
